const fs = require('fs');

let allObjects = [];

function readObjectsFromFileSync(path){
	return JSON.parse(fs.readFileSync(path, 'utf8'));
}

function writeObjectsToFileSync(path, objects){
	return fs.writeFileSync(path, JSON.stringify(objects));
}

module.exports.loadFileSync = function(path){
	allObjects = JSON.parse(fs.readFileSync(path, 'utf8'));
}

